import { CommonModule } from '@angular/common';
import { Component, Inject } from '@angular/core';
import { InputComponent } from '../../../../shared/components/input/input.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { BundlemanageService } from '../../../services/bundle-manage/bundlemanage.service';
import { SectionBuilderReq, UserSectionBuilderReq, } from '../../../interfaces/bundlemanage.interface';

@Component({
  selector: 'app-section-creation',
  standalone: true,
  imports: [CommonModule, InputComponent, ButtonComponent, IconComponent],
  templateUrl: './section-creation.component.html',
  styleUrl: './section-creation.component.scss'
})
export class SectionCreationComponent {
  cFolder: string = '';
  nSectionid: string;
  permission: string = 'N';
  nCaseid: string;
  cFoldertype: string;
  constructor(private dialogRef: MatDialogRef<SectionCreationComponent>, @Inject(MAT_DIALOG_DATA) public data: any, private bundleS: BundlemanageService) {
    this.nCaseid = data['nCaseid'];
    this.nSectionid = data['nSectionid'];
    this.cFoldertype = data['cFoldertype'] ? data['cFoldertype'] : null;
    this.cFolder = data['cFolder'] ? data['cFolder'] : null;
    if (this.nSectionid) {
      this.permission = 'E';
    }

  }

  async onSubmit() {
    if (this.cFolder.trim() != '') {
      let res: boolean;
      if (this.cFoldertype == 'CF') {
        var mdl: UserSectionBuilderReq = { nCaseid: this.nCaseid, nSectionid: this.nSectionid ? this.nSectionid : null, cFolder: this.cFolder, permission: this.permission, cFoldertype: this.cFoldertype };
        res = await this.bundleS.usersectionBuilder(mdl);
      } else {
        var mdl1: SectionBuilderReq = { nCaseid: this.nCaseid, nSectionid: this.nSectionid ? this.nSectionid : null, cFolder: this.cFolder, cFoldertype: this.cFoldertype, permission: this.permission };
        res = await this.bundleS.sectionBuilder(mdl1);
      }
      if (res) {
        this.dialogRef.close({ isSave: true })
      }
    }
  }

  close() {
    this.dialogRef.close();
  }
}
