import { Injectable } from '@angular/core';
import { environment } from '../../../../environments/environment';
import { firstValueFrom } from 'rxjs';
import { HttpClient, HttpParams } from '@angular/common/http';
import { hyperlinkList } from '../../interfaces/bundlemanage.interface';
import { TostbarService } from '../../../core/services/tost/tostbar.service';

@Injectable({
  providedIn: 'root'
})
export class HyperlinkService {

  hyperlinkList: hyperlinkList[] = [];
  constructor(private http: HttpClient, public tost: TostbarService) { }

  async getHyperLinks(nCaseid: string): Promise<any> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<any>(
          `${environment.hyperlinkservice}/hyperlinks`, //${environment.cloudUrl}
          { params: params }
        )
      );

      return res;
    } catch (err) {
      return null;
    }
  }

  async startHyperlink(nCaseid: string, nSectionid: string, nBundleid: string, nBundledetailid: string, cType: string, isIndex?: boolean, cKeeptype?: string, isDeep?: boolean): Promise<any> {
    const res = await this.hyperLinkMethod({ nCaseid, nSectionid,nBundleid, nBundledetailid, cType, cKeeptype: cKeeptype ? cKeeptype : 'R', isDeepscan: isDeep || false }, isIndex);
    if (res) {
      if (res.msg == 1) {
        if (res.data) {
          this.hyperlinkList.push(res.data)
          this.clearUnWanted();
        }
      }
    } else {
      this.tost.error('hyperlink failed');
    }
  }
  clearUnWanted(){
    this.hyperlinkList =  this.hyperlinkList.filter(a=>a.nTotal && a.nTotal >0 );
  }
  async hyperLinkMethod(mdl, isIndex: boolean): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.hyperlinkservice}/${isIndex ? 'indexhyperlink' : 'starthyperlink'}`, mdl) //${environment.cloudUrl}
      );
      if (res && res.msg == 1) {
        this.tost.success(res.value);
        return res;
      } else {
        this.tost.error(res.value);
        return res;
      }
    } catch (err) {
      this.tost.error(`hyperlink failed ${err}`);
      return { msg: -1, error: err, value: '' };
    }
  }

}
