import { Component, Inject, ViewChild, viewChild } from '@angular/core';
import { MatRadioModule } from '@angular/material/radio';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatSelectModule } from '@angular/material/select';
import { MatMenuModule } from '@angular/material/menu';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { InputComponent } from '../../../../shared/components/input/input.component';
import { ColorpickerComponent } from '../../../../shared/components/colorpicker/colorpicker.component';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { PaginationService } from '../../../services/pagination/pagination.service';
import { paginationDataRes, paginationRes } from '../../../interfaces/pagination.interface';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
@Component({
  selector: 'app-pagination',
  standalone: true,
  imports: [ButtonComponent, MatRadioModule, InputComponent, MatCheckboxModule, MatSelectModule, ColorpickerComponent, MatMenuModule, FormsModule, CommonModule],
  templateUrl: './pagination.component.html',
  styleUrl: './pagination.component.scss'
})
export class PaginationComponent {

  @ViewChild('preveref') preveref: any;
  colorslist = [{ cClr: '#ff0000' }, { cClr: '#00ff00' }, { cClr: '#0000ff' }];
  fonts: any = [
    { name: 'arial', text: 'Arial' },
    { name: 'verdana', text: 'Verdana' },
    { name: 'times', text: 'Times new roman' },
    { name: 'georgia', text: 'Georgia' }
  ]
  jPagination: any = { "fs": "16", "ft": "arial", "fc": "#000", "bc": "#fff", "cb": "#ffffff00", "position": "BR", "isHide": false };

  nType: number = 1;
  nStartpage: any = 0;
  nEndpage: any = 0;
  bPlacedefault: boolean = false;
  bPagedefault: boolean = false;

  cFontclr: any = '#ff0000';
  cBorderclr: any = '#ff0000';
  cBgclr: any = '#ff0000';
  bApplyall: boolean = false;
  nSectionid: any = 0;
  nBundledetailid: any = 0;
  nBundleid: any = 0;
  detail: paginationRes;
  // nUserid: number = parseInt(window.localStorage.getItem('nUserid'));
  constructor(private paginationS: PaginationService, private dialogRef: MatDialogRef<PaginationComponent>,
    @Inject(MAT_DIALOG_DATA) public data: string, private cf: CommonfunctionService) {
    if (data) {
      this.nSectionid = data['nSectionid'];
      this.nBundledetailid = data['nBundledetailid'];
      this.nBundleid = data['nBundleid'];
      if (this.nBundledetailid) {
        this.getPagination(data['nBundledetailid'])
      } else {
        this.nType = 2;
        this.nStartpage = 1;
        this.nEndpage = 1;
      }
    }
  }

  async getPagination(nBundledetailid) {
    let res: paginationRes = await this.paginationS.getPagination(nBundledetailid);
    this.detail = res;
    this.jPagination = this.detail.jPagination ? this.detail.jPagination : this.jPagination;
    this.jPagination.ft = this.jPagination.ft ? this.jPagination.ft.toLowerCase() : 'arial';
    if (this.detail && this.detail.cRefpage) {
      this.nType = 2;
      this.nStartpage = this.detail.cRefpage.split('-')[0];
      this.nEndpage = this.detail.cRefpage.split('-')[1];
    }
  }


  close(): void {
    this.dialogRef.close(false);
  }

  getStyles() {
    let styles = {
      // 'fontFamily': `${this.jPagination.ft}, sans-serif`,
      'fontSize': `${this.jPagination.fs}px`,
      'color': this.jPagination.fc,
      'backgroundColor': this.jPagination.bc,
      'border': `1px solid ${this.jPagination.cb}`,
      'bottom': this.jPagination.position.includes('B') ? '5px' : 'auto',
      'top': this.jPagination.position.includes('T') ? '10px' : 'auto',
      'right': this.jPagination.position.includes('R') ? '10px' : 'auto',
      'left': this.jPagination.position.includes('L') ? '10px' : 'auto'
    };
    return styles;
  }


  ngModelChange(event) {
    console.log("Font size changed to:", this.jPagination.fs);
    //alert(event)
    // You can also inspect the event to see what it contains
    console.log("Event data:", event);
  }

  dPlacement(flag) {
    if (flag) {
      this.jPagination = { "fs": "16", "ft": "arial", "fc": "#000", "bc": "#fff", "cb": "#ffffff00", "position": "BR", "isHide": false };
    }
  }

  dPagination(flag) {
    if (flag) {
      this.nStartpage = 1
      this.changeStart()
    }
  }


  changeStart() {
    if (this.detail && this.detail.cPage) {
      const splitPages = this.detail.cPage.split('-');
      if (splitPages.length > 1) {
        const diff = parseInt(splitPages[1]) - parseInt(splitPages[0]);
        this.nEndpage = parseInt(this.nStartpage) + diff;
      }
    } else {
      this.nEndpage = this.nStartpage;
    }
  }

  async submitPagination() {
    if (!this.nType) {
      return;
    }
    if (this.nType == 2 && (parseInt(this.nStartpage) < 1 || parseInt(this.nEndpage) < 1 || parseInt(this.nStartpage) > parseInt(this.nEndpage))) {
      return
    }

    if (this.nType == 1) {
      this.detail.cRefpage = null;
    }
    let paginationData: any = { isSave: true }
    if (this.bApplyall) {
      // && this.cf.paginationdata.nUserid != this.api.nUserid
      if (this.cf.isPagination == true) {
        // this.api.showError('Pagination already inprocess if you want to pagination stop pagination first');
        return;
      }

      paginationData = {
        isSave: true, cRefpage: this.nType == 2 ? (this.nStartpage + '-' + this.nEndpage) : null, jPagination: this.jPagination,
        cCreattype: this.nType, bPagedefault: this.bPagedefault, bApplyall: this.bApplyall
      }
      // this.dialogRef.close(paginationData);
    } else {
      // && this.cf.paginationdata.nUserid != this.api.nUserid
      if (this.cf.isPagination == true) {
        // this.api.showError('Pagination already inprocess if you want to pagination stop pagination first');
        return;
      }
    }

    var model: paginationDataRes = {
      nBundledetailid: this.nBundledetailid ? this.nBundledetailid : null,
      nBundleid: this.nBundleid,
      nSectionid: this.nSectionid,
      cRefpage: this.bPagedefault ? (this.detail && this.detail.cPage ? this.detail.cPage : (this.nStartpage + '-' + this.nEndpage)) : this.nType == 2 ? (this.nStartpage + '-' + this.nEndpage) : null,
      jPagination: this.jPagination,
      bApplyall: this.bApplyall,
      bPagedefault: this.bPagedefault,
      bIslater: false
    };
    let res: boolean = await this.paginationS.submitPagination(model);
    if (res) {
      // this.dialogRef.close({ isSave: true, cRefpage: this.nType == 2 ? (this.nStartpage + '-' + this.nEndpage) : null, jPagination: this.jPagination, cCreattype: this.nType, isbyDefault: this.bPagedefault, applyall: this.bApplyall });
      this.dialogRef.close(paginationData);
    }
  }



}

