import { ChangeDetectorRef, Component, Inject } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { MatRadioModule } from '@angular/material/radio';
import { InputComponent } from '../../input/input.component';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { FormsModule } from '@angular/forms';
import { ConvertType } from '../../../../adminpanel/interfaces/upload.interface';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatMenuModule } from '@angular/material/menu';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { MatSelectModule } from '@angular/material/select';

@Component({
  selector: 'app-convert-folder',
  standalone: true,
  imports: [FormsModule, IconComponent, ButtonComponent, MatCheckboxModule, MatRadioModule, MatMenuModule, MatSelectModule],
  templateUrl: './convert-folder.component.html',
  styleUrl: './convert-folder.component.scss'
})
export class ConvertFolderComponent {
  cBundletag: string = '';
  cName: string = '';
  isAuto: number = 1;
  filetypes: ConvertType[] = [];
  convertType: string = 'B';
  isAllconvert: boolean = false;
  bMetadata: boolean = true;
  selectedtype: any = 'ALL';
  jBids: string[] = [];
  jBDids: string[] = [];
  cFiletype: string = 'ALL';
  nSectionid: string; nBundleid: string;
  selectedtypes: string[] = []
  constructor(private dialogRef: MatDialogRef<ConvertFolderComponent>, @Inject(MAT_DIALOG_DATA) public data: any,
    private cd: ChangeDetectorRef, private mfs: MyfileService) {
    debugger;
    this.cName = data['cName'] ? data['cName'] : null;
    this.nBundleid = data['nBundleid'] ? data['nBundleid'] : null;
    this.nSectionid = data['nSectionid'] ? data['nSectionid'] : null;

    this.jBids = data['jBids'] ? data['jBids'] : [];
    this.jBDids = data['jBDids'] ? data['jBDids'] : [];
    this.cFiletype = data['cFiletype'] ? data['cFiletype'] : 'ALL';

  }

  ngOnInit() {
    debugger;
    if ((this.jBids && this.jBids.length) || (this.jBDids && this.jBDids.length)) {
      this.getFrtpes()
    } else if (this.nBundleid) {
      this.jBids = [this.nBundleid]
      this.getFrtpes()
    }
  }

  async getFrtpes() {
    let jBids = `{${this.jBids.map(e => e).toString()}}`;
    let jBDids = `{${this.jBDids.map(e => e).toString()}}`;
    let data: any = await this.mfs.getFileTypes(jBids, jBDids, this.nSectionid);
    data.map(a => a['isConvert'] = true);
    this.filetypes = data;
    this.select()
  }


  allConvertChange(event: any): void {
    this.filetypes.map(a => a.isConvert = event.checked);
    this.cd.detectChanges();
    return;
  }

  async onSubmit() {
    const jFtypes = this.filetypes.filter(a => a.isConvert).map(e => e.type)
    let jBids = `{${this.jBids.map(e => e).toString()}}`;
    let jBDids = `{${this.jBDids.map(e => e).toString()}}`;
    this.dialogRef.close({ isSave: true, jBids: jBids, jBDids: jBDids, jFtypes: jFtypes, cConvertType: this.convertType, bMetadata: this.bMetadata })
  }



  close() {
    this.dialogRef.close();
  }


  select() {
    if (this.filetypes.filter(a => a.isConvert).length == this.filetypes.length) {
      this.isAllconvert = true;
    } else {
      this.isAllconvert = false;
    }
  }

  checklength() {
    if (this.filetypes.length && this.filetypes.filter(e => e.isConvert).length) {
      return false
    }
    return true
  }
}

