import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, Input } from '@angular/core';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { AvatarComponent } from '../../avatar/avatar.component';
import { CommonModule } from '@angular/common';
import { MAT_DIALOG_DATA, MatDialog } from '@angular/material/dialog';
import { MatSlideToggleModule } from '@angular/material/slide-toggle';
import { FormsModule } from '@angular/forms';
import { IconComponent } from '../../icon/icon.component';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';

@Component({
  selector: 'app-permission',
  standalone: true,
  imports: [CommonModule, FormsModule, AvatarComponent, MatSlideToggleModule, IconComponent],
  templateUrl: './permission.component.html',
  styleUrl: './permission.component.scss',
  providers: [MyfileService]
})
export class PermissionComponent {
  nCaseid: string;
  nBundleid: string;
  nBundledetailid: string;
  teamlist = [];
  users = [];
  userDetail: any = {}
  nTeamid: string;
  constructor(private myfileS: MyfileService, @Inject(MAT_DIALOG_DATA) public data: any, private dialog: MatDialog,
    private ss: SecureStorageService) {
    this.nCaseid = data['nCaseid'];
    this.nBundleid = data['nBundleid'];
    this.nBundledetailid = data['nBundledetailid'];
  }

  async ngOnInit() {
    this.userDetail = await this.ss.getUserInfo();
    this.getTeamList();
  }

  async getTeamList() {
    var res = await this.myfileS.teamuserList(this.nCaseid)
    this.teamlist = res;
    for (let team of this.teamlist) {
      if (team.users.length && team.users.find(e => e.nUserid == this.userDetail.nUserid)) {
        this.nTeamid = team.nTeamid;
        break;
      }
    }

    this.getUserlist();
  }

  async getUserlist() {
    var mdl = { nBundleid: this.nBundleid, nBundledetailid: this.nBundledetailid };
    var res = await this.myfileS.bundlesPermission(mdl);
    this.users = res;

    // Convert this.users to a Set for quick lookup
    const userIdSet = new Set(this.users.map(user => user.nUserid));

    // Process each team and user more efficiently

    this.teamlist = this.teamlist.map(team => {
      const updatedUsers = team.users.map(user => ({
        ...user,
        isCheck: !userIdSet.has(user.nUserid)  // Set isCheck based on absence in userIdSet
      }));

      // Check if all users in the team are checked
      const isAllUsersChecked = updatedUsers.every(user => user.isCheck);

      return {
        ...team,
        users: updatedUsers,
        isCheck: isAllUsersChecked  // Set the team's check status based on all users' check status
      };
    });

  }



  checkall(x) {
    x.users.map(a => a.isCheck = x.isCheck);
    this.update_permission(x);
  }

  checkuser(x) {
    this.update_permission(x);
  }


  update_permission(mn) {
    var mdl = { nCaseid: this.nCaseid, nBundleid: this.nBundleid, nBundledetailid: this.nBundledetailid, nUserid: mn.nUserid ? mn.nUserid : 0, nTeamid: mn.nTeamid ? mn.nTeamid : 0, bPermit: mn.isCheck }
    this.myfileS.setPermission(mdl).then(res => {
      if (res) { }
    })
  }


  close() {
    this.dialog.closeAll();
  }
}
