import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { Component, Inject } from '@angular/core';
import { IconComponent } from '../../icon/icon.component';
import { ButtonComponent } from '../../button/button.component';
import { InputComponent } from '../../input/input.component';
import { MatRadioModule } from '@angular/material/radio';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-update-bundletag',
  standalone: true,
  imports: [FormsModule, IconComponent, ButtonComponent, InputComponent, MatRadioModule],
  templateUrl: './update-bundletag.component.html',
  styleUrl: './update-bundletag.component.scss'
})
export class UpdateBundletagComponent {
  cBundletag: string = '';
  cName: string = '';
  isAuto: number = 1;
  constructor(private dialogRef: MatDialogRef<UpdateBundletagComponent>, @Inject(MAT_DIALOG_DATA) public data: any) {
    this.cBundletag = data['cBundletag'] ? data['cBundletag'] : null;
    this.cName = data['cName'] ? data['cName'] : null;
  }

  async onSubmit() {
    if (this.cBundletag.trim() != '') {
      this.dialogRef.close({ isSave: true, "cBundletag": this.cBundletag, isAuto: this.isAuto == 1 ? true : false })
    }
  }

  close() {
    this.dialogRef.close();
  }
}
