import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges } from '@angular/core';
import { MatMenuModule } from '@angular/material/menu';
import { SectionBuilderReq, SectionRes, UserSectionBuilderReq } from '../../../../adminpanel/interfaces/bundlemanage.interface';
import { BundlemanageService } from '../../../../adminpanel/services/bundle-manage/bundlemanage.service';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { MatSelectModule } from '@angular/material/select';
import { MatFormFieldModule } from '@angular/material/form-field';
import { FormsModule } from '@angular/forms';
import { SectionCreationComponent } from '../../../../adminpanel/components/bundlemanagement/section-creation/section-creation.component';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { Subscription } from 'rxjs';
import { CommunicationService } from '../../../services/communication/communication.service';
import { SharewithteamComponent } from '../sharewithteam/sharewithteam.component';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { HeaderService } from '../../../../core/services/header/header.service';
import { TranslateModule } from '@ngx-translate/core';
import {
  SECTION_DIALOG,
  SECTION_EVENTS,
  SECTION_FOLDER_TYPES,
  SECTION_APPROVED_EXCLUDE_TYPES,
  SECTION_PANEL_CLASS,
  SECTION_TEMPLATE_LIST,
  SectionTemplateItem
} from '../../../interfaces/section.interface';

@Component({
  selector: 'app-section',
  standalone: true,
  imports: [CommonModule, MatMenuModule, ButtonComponent, IconComponent, MatSelectModule, MatFormFieldModule, FormsModule, MatDialogModule, NgScrollbarModule, TranslateModule],
  templateUrl: './section.component.html',
  styleUrl: './section.component.scss'
})
export class SectionComponent implements OnInit, OnChanges, OnDestroy {
  readonly FOLDER_TYPES = SECTION_FOLDER_TYPES;
  readonly APPROVED_EXCLUDE_TYPES: readonly string[] = SECTION_APPROVED_EXCLUDE_TYPES;
  @Output() changeSection: EventEmitter<any> = new EventEmitter();
  @Output() allSection: EventEmitter<SectionRes[] | SectionRes[][]> = new EventEmitter();
  @Input() nCaseid: string;
  @Input() isadmin: boolean;
  @Input() activeSection: SectionRes;
  @Input() disabled: boolean = false;
  @Input() isDownload: boolean = false;
  sectionlist: SectionRes[];
  sectionlist2: SectionRes[];
  readonly sectionlist2D: SectionTemplateItem[] = SECTION_TEMPLATE_LIST;
  corebundle: SectionRes[] = [];
  Generic: SectionRes[] = [];
  evsubscription: Subscription;
  @Input() isChooser: boolean = false;
  @Input() nPresentid: string;
  @Input() presentDocType: string;
  @Input() isUser: boolean = false;
  @Input() nSectionid: string;
  constructor(
    private readonly bundleS: BundlemanageService,
    private readonly dialog: MatDialog,
    private readonly cdr: ChangeDetectorRef,
    private readonly cs: CommunicationService,
    private readonly hs: HeaderService
  ) {
  }

  ngOnInit(): void {
    this.getSections();
    this.checkEventSub()
  }

  checkEventSub(): void {
    this.evsubscription = this.cs.functionCalled$.subscribe((data: any) => {
      if (data === SECTION_EVENTS.RELOAD_SECTION) {
        this.getSections(true);
        return;
      }

      if (data?.type === SECTION_EVENTS.ACTIVE_SECTION) {
        this.addSection(data);
        return;
      }

      if (data?.type !== SECTION_EVENTS.CHANGE_SECTION) return;

      const byId = data?.nSectionid
        ? this.sectionlist?.find(e => e.nSectionid == data.nSectionid)
        : undefined;

      if (byId) {
        this.sectionChange(byId);
        return;
      }

      const folderType = data?.cFoldertype;
      if (!folderType) return;

      const isCoreBundle = folderType === SECTION_FOLDER_TYPES.CORE_BUNDLE;

      // Folder types live in different lists depending on the user role and
      // exclusion rules — TRANSCRIPT (TS), USER_FILES (CF), and CORE_BUNDLE
      // (CB) sit in sectionlist2 for non-admin users (SECTION_APPROVED_EXCLUDE_TYPES
      // strips them out of sectionlist for the user select) while MASTER_BUNDLE
      // and others stay in sectionlist. Search both rather than picking one
      // up-front so callers don't need to know which bucket the type lives in.
      const findInBoth = (): SectionRes | undefined => {
        const fromMain = (this.sectionlist ?? []).find(e => e.cFoldertype == folderType);
        if (fromMain) return fromMain;
        return (this.sectionlist2 ?? []).find(e => e.cFoldertype == folderType);
      };

      const hasActive = (): boolean => {
        const match = findInBoth();
        return !!match && !!match.isActive;
      };

      if (isCoreBundle && !hasActive()) {
        const sectionToAdd = (this.sectionlist2 ?? []).find(e => e.cFoldertype == folderType);
        if (sectionToAdd) this.addSection(sectionToAdd);

        const intervalId = setInterval(() => {
          const section = findInBoth();
          if (!section) return;
          this.sectionChange(section);
          clearInterval(intervalId);
        }, 200);
        return;
      }

      const existing = findInBoth();
      if (existing) {
        this.sectionChange(existing);
        return;
      }

      // Section list may not be loaded yet (this fires from a cross-window
      // postMessage right after navigating into Evidence). Poll briefly so we
      // don't lose the request — give up after ~3s to avoid hanging.
      let attempts = 0;
      const intervalId = setInterval(() => {
        attempts++;
        const section = findInBoth();
        if (section) {
          this.sectionChange(section);
          clearInterval(intervalId);
          return;
        }
        if (attempts >= 15) clearInterval(intervalId);
      }, 200);
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    this.cdr.detectChanges();
  }

  ngOnDestroy(): void {
    this.evsubscription?.unsubscribe();
  }

  getSections(isChange: boolean = false): void {
    if (this.isadmin) {
      this.loadAdminSections();
      return;
    }
    this.loadUserSections(isChange);
  }

  private loadUserSections(isChange: boolean): void {
    const method = this.isDownload ? 'getUploadSections' : 'getUserSections';
    this.bundleS[method](this.nCaseid).then(res => {
      this.sectionlist = res[0] ?? [];
      this.sectionlist2 = res[1] ?? [];

      this.corebundle = this.sectionlist.filter(e => e.cFoldertype == SECTION_FOLDER_TYPES.CORE_ASSIGNED);
      this.Generic = this.sectionlist.filter(e => e.cFoldertype == SECTION_FOLDER_TYPES.GENERIC);
      const mb = this.sectionlist.filter(e => e.cFoldertype == SECTION_FOLDER_TYPES.MASTER_BUNDLE);

      const allSectionList = [mb, this.corebundle, this.Generic, this.sectionlist2];
      this.allSection.emit(allSectionList);

      const allFlatSections = [...mb, ...this.corebundle, ...this.Generic, ...this.sectionlist2];

      if (this.isUser && this.nSectionid) {
        const section = this.sectionlist2.find(e => e.nSectionid == this.nSectionid);
        if (section?.nSectionid) this.sectionChange(section);
        return;
      }

      if (!isChange) {
        const mbSection = this.sectionlist.find(e => e.cFoldertype == SECTION_FOLDER_TYPES.MASTER_BUNDLE);
        if (mbSection) {
          this.sectionChange(mbSection);
        } else if (this.sectionlist?.length) {
          // Keep existing behavior: emit the MB group (array) if nothing else.
          this.sectionChange(allSectionList[0] as any);
        }
        return;
      }

      if (this.activeSection?.cFoldertype === SECTION_FOLDER_TYPES.ALL) return;

      const currentId = this.activeSection?.nSectionid;
      if (currentId) {
        const match = allFlatSections.find(e => e.nSectionid == currentId);
        if (match) this.sectionChange(match);
      }
      this.cdr.detectChanges();
    });
  }

  private loadAdminSections(): void {
    this.bundleS.getSections(this.nCaseid).then(res => {
      this.sectionlist = res ?? [];
      this.corebundle = this.sectionlist.filter(e => e.cFoldertype == SECTION_FOLDER_TYPES.CORE_ASSIGNED);
      this.Generic = this.sectionlist.filter(e => e.cFoldertype == SECTION_FOLDER_TYPES.GENERIC);

      const mbSection = this.sectionlist.find(e => e.cFoldertype == SECTION_FOLDER_TYPES.MASTER_BUNDLE);
      if (mbSection) this.sectionChange(mbSection);
      this.allSection.emit(this.sectionlist);
    });
  }

  getShare(nSectionid: string): void {
    const dialogRef = this.dialog.open(SharewithteamComponent, {

      width: SECTION_DIALOG.SHARE_WIDTH,
      height: SECTION_DIALOG.SHARE_HEIGHT,
      panelClass: [...SECTION_PANEL_CLASS],
      data: {
        nBundleid: null,
        nBundledetailid: null,
        nCaseid: this.nCaseid,
        nSectionid: nSectionid,
      }
    });
    dialogRef.afterClosed().subscribe();
  }

  sectionChange(e: any) {
    this.activeSection = e;
    this.changeSection.emit(e);
    if (this.hs.isGlobalSearch) {
      setTimeout(() => {
        this.cs.callFunction({ event: 'SEARCH_FILES_EXISTING_FILTER' });
      });
    }
  }

  async addSection(x: any): Promise<void> {
    if (this.isadmin) return;

    if (x.cFoldertype == SECTION_FOLDER_TYPES.USER_FILES) {
      this.createSection(x);
      return;
    }
    if (x.isActive) return;

    const mdl: UserSectionBuilderReq = {
      nCaseid: this.nCaseid,
      nSectionid: x?.nSectionid ?? null,
      cFolder: x.cFolder,
      permission: 'N',
      cFoldertype: x.cFoldertype
    };
    const res: any = await this.bundleS.usersectionBuilder(mdl);
    if (res) this.getSections();
  }

  createSection(x?: any): void {
    const data: any = {
      nCaseid: this.nCaseid,
      nSectionid: x?.nSectionid ?? null,
      cFolder: x?.cFolder ?? null,
      cFoldertype: x?.cFoldertype ?? null
    }
    this.openModle(SectionCreationComponent, data, SECTION_DIALOG.CREATE_WIDTH)
  }

  openModle(component: any, data: SectionBuilderReq, width?: string, height?: string): void {
    const dialogRef = this.dialog.open(component, {
      width: width ?? SECTION_DIALOG.DEFAULT_DIMENSION,
      height: height ?? SECTION_DIALOG.DEFAULT_DIMENSION,
      maxHeight: SECTION_DIALOG.MAX_HEIGHT,
      panelClass: [...SECTION_PANEL_CLASS],
      data: data
    });
    dialogRef.afterClosed().subscribe(result => {
      this.handleDialogClose(result, component, data);
    });
  }

  private handleDialogClose(result: any, component: any, data: SectionBuilderReq): void {
    if (!result?.isSave) return;
    if (component !== SectionCreationComponent) return;

    const sectionId = (data as any)["nSectionid"];
    if (sectionId) {
      if (this.activeSection?.nSectionid == sectionId) {
        this.activeSection.cFolder = (data as any)["cFolder"] ?? this.activeSection.cFolder;
      }
      this.getSections(!this.isadmin);
      this.cdr.detectChanges();
      return;
    }
    this.getSections();
    this.cdr.detectChanges();
  }

  async deleteSection(x: any): Promise<void> {
    const mdl: SectionBuilderReq = {
      nCaseid: this.nCaseid,
      nSectionid: x.nSectionid ? x.nSectionid : null,
      cFolder: x.cFolder,
      cFoldertype: x.cFoldertype,
      permission: 'D'
    };
    const res: any = await this.bundleS.sectionBuilder(mdl);
    if (res) {
      this.bundleS.getSections(this.nCaseid).then(res => {
        this.getSections();
        const mbSection = res?.find(e => e.cFoldertype == SECTION_FOLDER_TYPES.MASTER_BUNDLE);
        if (mbSection) this.sectionChange(mbSection);
      });
    }
  }
}
