import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { MatMenuModule, MatMenuTrigger } from '@angular/material/menu';
import { bundleRes, SharedByUser } from '../../../interfaces/myfile.interface';
import { BehaviorSubject, Subscription } from 'rxjs';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { MatDialog } from '@angular/material/dialog';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { CommunicationService } from '../../../services/communication/communication.service';
import { CommonModule } from '@angular/common';
import { ScrollingModule } from '@angular/cdk/scrolling';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { IconComponent } from '../../icon/icon.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { SkeletonComponent } from '../../skeleton/skeleton.component';
import { EmptyComponent } from '../../empty/empty.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatFormFieldModule } from '@angular/material/form-field';
import { FormsModule } from '@angular/forms';
import { TruncateTooltipDirective } from '../../../directive/truncate-tooltip.directive';

/** Flat node with expandable and level information */
interface ExampleFlatNode {
  nBundleid: string;
  nParentBundleid: string;
  cBundlename: string;
  cBundletag?: string;
  level?: number;
  isedit?: boolean;
  isNew?: boolean;
  isExpanded?: boolean;
  cIscheck?: boolean;
  islodingchildren?: boolean;
}

@Component({
  selector: 'sharedfolder',
  standalone: true,
  imports: [CommonModule, ScrollingModule, NgScrollbarModule, IconComponent, MatCheckboxModule, SkeletonComponent, EmptyComponent, MatTooltipModule,
    MatFormFieldModule, MatMenuModule, FormsModule, TruncateTooltipDirective],
  templateUrl: './sharedfolder.component.html',
  styleUrl: './sharedfolder.component.scss'
})
export class SharedfolderComponent {

  @Input() menuTrigger: MatMenuTrigger;
  @Input() isSepcomponent: boolean;
  @Input() nSectionid: string;
  @Input() nUserid: string;
  @Input() cFoldertype: string;
  @Input() nCaseid: string;
  @Input() nBundleid: string;
  @Input() changeF: boolean;
  @Input() cutCopyType: string;
  @Input() isIndividual: boolean = false;
  @Input() selectedIDs: string[] = [];
  @Output() changeFolder: EventEmitter<string> = new EventEmitter();
  @Output() getSelection: EventEmitter<string> = new EventEmitter();
  activeBundle: bundleRes;
  loading: boolean = true;
  TREE_DATA: ExampleFlatNode[] = [];
  isCopy: boolean = false;
  sharedByuser: SharedByUser[] = [];
  private evsubscription: Subscription;
  constructor(public myfileS: MyfileService, private cdr: ChangeDetectorRef, private dialog: MatDialog,
    private cs: CommunicationService, private cf: CommonfunctionService
  ) {
    this.checkEventSub();
  }



  async checkEventSub() {
    this.evsubscription = this.cs.functionCalled$.subscribe(async (data) => {
      if (data && data.event && data.event == 'CB-SECTION') {
        if (data.isSection) {
          // this.TREE_DATA.map(e => e.isExpanded = false);

          this.activeBundle = null;
          var treedata = [...this.TREE_DATA];
          for (let row of treedata.filter(e => e.nParentBundleid == null)) {
            row.isExpanded = false;
            this.TREE_DATA = this.removeDescendants(this.TREE_DATA, row.nBundleid);
          }
          this.selectedFolder(null);
          this.changeFolder.emit('SELECTED')
        }
      }
    })
  }

  ngOnDestroy() {
    this.evsubscription.unsubscribe();
  }

  ngOnInit() {

  }

  ngAfterViewInit(): void {

  }




  ngOnChanges(changes: SimpleChanges) {
    if (changes['nSectionid'] && this.nSectionid) {
      this.getSharedBundleList(null);
    }
  }

  async getSharedBundleList(node) {
    try {
      let res1 = await this.myfileS.getSharedBundles(this.nSectionid, this.nUserid);
      let res = res1 && res1.length ? res1 : []
      res.map(e => { e["level"] = 0; e["expandable"] = false });
      this.TREE_DATA = res;
      if (res.length) {
        this.changeFolder.emit('GET_BUNDLE_LIST')
      }

      this.loading = false;

      this.cdr.detectChanges();
    } catch (error) {
      // Handle error
      console.error('Error fetching bundle list:', error);
    }

    this.changeFolder.emit('SELECTED')
  }

  async getBundleList(node) {
    try {
      var mdl = { nSectionid: this.nSectionid, nBundleid: node && node.nBundleid ? node.nBundleid : null, pageNumber: 1 }
      var res = await this.myfileS.bundleList(mdl);

      if (mdl.nBundleid && node) {
        var ind = this.TREE_DATA.findIndex(e => e.nBundleid == mdl.nBundleid);
        res.map(e => { e["level"] = node["level"] + 1; e["expandable"] = false, e["cIscheck"] = node["cIscheck"] });
        if (!this.TREE_DATA.filter(e => e.nBundleid && e.nParentBundleid == node.nBundleid).length) {
          var isnew = this.TREE_DATA.filter(e => !e.nBundleid && e.nParentBundleid == node.nBundleid && e.isNew).length ? true : false;
          const updatedTreeData = [
            ...this.TREE_DATA.slice(0, ind + 1 + (isnew ? 1 : 0)),
            ...res,
            ...this.TREE_DATA.slice(ind + 1 + (isnew ? 1 : 0))
          ];
          this.TREE_DATA = updatedTreeData;
          node.isExpanded = true;
        }
        this.selectedFolder(node);
        node.islodingchildren = false;
      } else {
        res.map(e => { e["level"] = 0; e["expandable"] = false });
        this.TREE_DATA = res;
      }
      if (res.length) {
        this.changeFolder.emit('GET_BUNDLE_LIST')
      }

      this.loading = false;

      this.cdr.detectChanges();
    } catch (error) {
      // Handle error
      console.error('Error fetching bundle list:', error);
    }

    this.changeFolder.emit('SELECTED')
  }


  loadChildren(node, flag?) {

    if (node && node.nBundleid && this.checkCopy() && this.cutCopyType == 'Cut') {
      var resultArray = this.getcheckedFolder().map(e => e.nBundleid)
      if (resultArray.includes(node.nBundleid)) {
        return;
      }
    }

    if (node && node.islodingchildren) { return }
    if (node && node.isExpanded) {
      node.islodingchildren = false;
      if (flag && this.activeBundle == node) {
        if (this.activeBundle == node) {
          node.isExpanded = false;
          this.TREE_DATA = this.removeDescendants(this.TREE_DATA, node.nBundleid);
          if (node.level > 0) {
            var parentNode = this.TREE_DATA.find(parent => node.nParentBundleid === parent.nBundleid);
            this.activeBundle = node;
            this.selectedFolder(parentNode);
          } else {
            this.activeBundle = null;
            this.selectedFolder(null);
          }
        }
        this.cdr.detectChanges();
      } else {
        this.activeBundle = node;

        var treedata = [...this.TREE_DATA];
        for (let row of treedata.filter(e => e.nParentBundleid == node.nBundleid)) {
          row.isExpanded = false;
          this.TREE_DATA = this.removeDescendants(this.TREE_DATA, row.nBundleid);
        }
        this.selectedFolder(node)
      }
      this.changeFolder.emit('SELECTED')
    } else if (node) {
      node.isExpanded = true;
      node.islodingchildren = true;
      this.activeBundle = node;
      this.getBundleList(node)
    } else {
      this.activeBundle = null;
      var treedata = [...this.TREE_DATA];
      for (let row of treedata.filter(e => e.nParentBundleid == null)) {
        row.isExpanded = false;
        this.TREE_DATA = this.removeDescendants(this.TREE_DATA, row.nBundleid);
      }
      this.selectedFolder(null);
      this.changeFolder.emit('SELECTED')
    }



  }


  refreshNode(nBundleid) {

    var node = this.TREE_DATA.find(e => e.nBundleid == nBundleid);
    if (node) {
      if (node["isExpanded"]) {
        this.TREE_DATA = this.removeDescendants(this.TREE_DATA, node.nBundleid);
        this.getBundleList(node);

      }
    } else {
      this.getBundleList(null);
    }
    this.cdr.detectChanges();
  }



  removeDescendants(treeData, nodeId) {
    if (!nodeId) return treeData.filter(e => e.nBundleid);
    const startIndex = treeData.findIndex(node => node.nParentBundleid === nodeId);
    if (startIndex === -1) {
      // Parent id not found, return the original array
      return treeData;
    }

    let endIndex = treeData.length;
    for (let i = startIndex + 1; i < treeData.length; i++) {
      if (treeData[i].level < treeData[startIndex].level) {
        endIndex = i;
        break;
      }
    }
    // Remove the descendants from the array
    return [...treeData.slice(0, startIndex), ...treeData.slice(endIndex)];
  }



  selectedFolder(node?) {
    var brdcrumb: any = { brdcrumb: node ? this.getNodePath(node).map(e => { return { nBundleid: e.nBundleid, cBundlename: e.cBundlename } }) : [] };
    this.changeFolder.emit(brdcrumb);
  }


  getNodePath(node: any): any[] {
    const path = [node];
    let currentNode = node;

    // Continue until no parent is found
    if (currentNode.nParentBundleid) {
      while (currentNode) {
        const parent = this.TREE_DATA.filter(e => e.nBundleid).find(parent => currentNode.level > parent.level && currentNode.nParentBundleid === parent.nBundleid);
        if (parent) {
          path.unshift(parent);
          currentNode = parent;
        } else {
          break; // Exit loop if no parent is found
        }
      }
    }

    return path; // Return the complete path from root to the node
  }


  getParentNode(node: ExampleFlatNode) {
    const nodeIndex = this.TREE_DATA.indexOf(node);
    for (let i = nodeIndex - 1; i >= 0; i--) {
      if (this.TREE_DATA[i].level === node.level - 1) {
        return this.TREE_DATA[i];
      }
    }

    return null;
  }

  shouldRender(node: ExampleFlatNode) {
    let parent = this.getParentNode(node);
    while (parent) {
      if (!parent.isExpanded) {
        return false;
      }
      parent = this.getParentNode(parent);
    }
    return true;
  }

  onDragStart(event: DragEvent, item: any) {
    this.myfileS.isfolderdraging = true;
    var path = this.getNodePath(item).map(e => e.cBundlename);
    var draggedItem = { id: item.nBundleid, path: path, isactive: '' };
    event.dataTransfer?.setData('text', JSON.stringify(draggedItem));
    console.log(JSON.stringify(draggedItem))
  }


  openfolderuncheck(node, event) {
    this.loadChildren(node, true);
    this.TREE_DATA.map(e => e["cIstempcheck"] = false)
    node.cIstempcheck = event.checked;
    this.cdr.detectChanges();
  }

  onDragEnd() {
    this.myfileS.isfolderdraging = false;
  }

  checkFolder(node, event) {
    // this.loadChildren(node, true)
    if (event.checked && this.checkCopy()) {
      this.TREE_DATA.map(e => e["cIscheck"] = false)
      node.cIscheck = event.checked;
      this.changeFolder.emit('SELECTED')
      return;
    }
    node.cIscheck = event.checked;
    this.selectAllChildern(node, event);
    this.changeFolder.emit('SELECTED')
  }



  selectAllChildern(node, event) {
    const startIndex = this.TREE_DATA.findIndex(data => data.nParentBundleid === node.nBundleid);
    if (startIndex === -1) {
      return;
    }

    let endIndex = this.TREE_DATA.length;
    for (let i = startIndex + 1; i < this.TREE_DATA.length; i++) {
      if (this.TREE_DATA[i].level < this.TREE_DATA[startIndex].level) {
        endIndex = i;
        break;
      }
    }

    for (let i = startIndex; i < endIndex; i++) {
      this.TREE_DATA[i]["cIscheck"] = event.checked;
    }

    return;
  }



  finalizeNode(node) {
    node.isedit = false;
    node.isNew = false;
  }

  removeNodeFromTree(node) {
    const ind = this.TREE_DATA.findIndex(e => e.nBundleid === node.nBundleid);
    if (ind > -1) {
      // Creating a new array reference so Angular detects the change
      this.TREE_DATA = [...this.TREE_DATA.slice(0, ind), ...this.TREE_DATA.slice(ind + 1)];
    }
  }

  refreshTree() {
    this.cdr.detectChanges();
  }

  checkCopy() {
    if (this.cutCopyType) {
      return true;
    }
    return false;
  }

  getcheckedFolder() {
    const expandedNodes: any = [];
    // Iterate through all nodes in the data source
    this.TREE_DATA.forEach(node => {
      // Check if the node is expanded
      if (node["cIscheck"]) {
        expandedNodes.push(node);
      }
    });
    return expandedNodes;
  }



  async closeMenu() {
    this.changeFolder.emit('SUBMIT')
    this.menuTrigger.closeMenu()
  }


}
